L[#L+1] = "var UI = \"en\";"
L[#L+1] = ""
L[#L+1] = "function t(key) {"
L[#L+1] = "  var table = STRINGS[UI] || {};"
L[#L+1] = "  var s = table[key];"
L[#L+1] = "  if (s === undefined) s = (STRINGS.en || {})[key];"
L[#L+1] = "  if (s === undefined) return key;"
L[#L+1] = "  for (var i = 1; i < arguments.length; i++) {"
L[#L+1] = "    s = s.split(\"{\" + (i - 1) + \"}\").join(String(arguments[i]));"
L[#L+1] = "  }"
L[#L+1] = "  return s;"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Setzt alle mit data-i18n bzw. data-i18n-ph markierten Texte neu. */"
L[#L+1] = "function applyStrings() {"
L[#L+1] = "  var nodes = document.querySelectorAll(\"[data-i18n]\");"
L[#L+1] = "  for (var i = 0; i < nodes.length; i++) {"
L[#L+1] = "    nodes[i].textContent = t(nodes[i].getAttribute(\"data-i18n\"));"
L[#L+1] = "  }"
L[#L+1] = "  nodes = document.querySelectorAll(\"[data-i18n-ph]\");"
L[#L+1] = "  for (var j = 0; j < nodes.length; j++) {"
L[#L+1] = "    nodes[j].placeholder = t(nodes[j].getAttribute(\"data-i18n-ph\"));"
L[#L+1] = "  }"
L[#L+1] = "  /* Knoepfe, die nur ein Symbol zeigen: der Text gehoert in title UND in"
L[#L+1] = "     aria-label, sonst ist der Knopf fuer Vorlesewerkzeuge stumm. */"
L[#L+1] = "  nodes = document.querySelectorAll(\"[data-i18n-title]\");"
L[#L+1] = "  for (var m = 0; m < nodes.length; m++) {"
L[#L+1] = "    var beschriftung = t(nodes[m].getAttribute(\"data-i18n-title\"));"
L[#L+1] = "    nodes[m].title = beschriftung;"
L[#L+1] = "    nodes[m].setAttribute(\"aria-label\", beschriftung);"
L[#L+1] = "  }"
L[#L+1] = "  document.documentElement.lang = UI;"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "function pickUiLang() {"
L[#L+1] = "  var wanted = PAYLOAD.uiLang || (navigator.language || \"en\").slice(0, 2);"
L[#L+1] = "  return STRINGS[wanted] ? wanted : \"en\";"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "var API = \"https://www.wikidata.org/w/api.php\";"
L[#L+1] = "var MIN_CHARS = 3, DEBOUNCE = 250, MAX_HITS = 8;"
L[#L+1] = ""
L[#L+1] = "/* ---------------------------------------------------------------------------"
L[#L+1] = "   Neues Wikidata-Element anlegen (Tool \"New Q5\" auf Toolforge)."
L[#L+1] = ""
L[#L+1] = "   Wer auf einem Festival fotografiert, trifft regelmäßig auf Personen, die"
L[#L+1] = "   in Wikidata noch gar nicht stehen. Dann hilft die beste Suche nichts - es"
L[#L+1] = "   muss erst ein Eintrag entstehen. Das Tool legt genau solche Personen an"
L[#L+1] = "   (Q5 = Mensch)."
L[#L+1] = ""
L[#L+1] = "   Das Tool kann KEINE Werte entgegennehmen, nur die Auswahl der Felder, die"
L[#L+1] = "   es zum Ausfüllen anbietet - Muster ?property=P1|P2|P3. Der getippte Name"
L[#L+1] = "   reist also nicht mit; er muss dort erneut eingegeben werden."
L[#L+1] = ""
L[#L+1] = "   Die Vorauswahl unten ist auf Porträts von Filmschaffenden gemünzt:"
L[#L+1] = "   Geschlecht, Geburtsdatum, Tätigkeit, Staatsangehörigkeit, IMDb-Kennung."
L[#L+1] = "   Wer andere Felder braucht, ändert NUR diese eine Zeile."
L[#L+1] = "--------------------------------------------------------------------------- */"
L[#L+1] = "var NEU_ITEM_BASIS  = \"https://new-q5.toolforge.org/\";"
L[#L+1] = "var NEU_ITEM_FELDER = [\"P21\", \"P569\", \"P106\", \"P27\", \"P345\"];"
L[#L+1] = ""
L[#L+1] = "function neuItemUrl(){"
L[#L+1] = "  /* Adresse ausschliesslich aus festen Bestandteilen: die Basis ist eine"
L[#L+1] = "     Konstante, die Feldkennungen werden gegen ^P[1-9][0-9]*$ geprueft und"
L[#L+1] = "     zusaetzlich kodiert. Damit kann hier nichts Fremdes in ein href geraten. */"
L[#L+1] = "  var gut = [];"
L[#L+1] = "  for (var i = 0; i < NEU_ITEM_FELDER.length; i++) {"
L[#L+1] = "    var p = String(NEU_ITEM_FELDER[i] || \"\");"
L[#L+1] = "    if (/^P[1-9][0-9]*$/.test(p)) gut.push(p);"
L[#L+1] = "  }"
L[#L+1] = "  if (!gut.length) return NEU_ITEM_BASIS;"
L[#L+1] = "  return NEU_ITEM_BASIS + \"?property=\" + encodeURIComponent(gut.join(\"|\"));"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* ---------------------------------------------------------------------------"
L[#L+1] = "   Zustand. depicts und createdDuring sind Listen aus {id, label}; die"
L[#L+1] = "   Zeichenketten des Zusatzmoduls werden beim Laden zerlegt und beim Speichern"
L[#L+1] = "   wieder zusammengesetzt."
L[#L+1] = "--------------------------------------------------------------------------- */"
L[#L+1] = "var state = { depicts: [], createdDuring: null, categories: [], captions: [],"
L[#L+1] = "              freetext: \"\", connectors: {}, forms: {}, workflow: \"\","
L[#L+1] = "              applyToAll: false, eventTemplate: \"\", gallery: \"\" };"
L[#L+1] = ""
L[#L+1] = "/* Was Wikidata ueber die benutzten Q-Items weiss. Wird beim Erzeugen gefuellt"
L[#L+1] = "   und dann in COMPOSE hineingegeben. */"
L[#L+1] = "var DETAILS = { labels: {}, sitelinks: {}, human: {}, conn: {}, form: {} };"
L[#L+1] = "var dirty = false;"
L[#L+1] = ""
L[#L+1] = "/* Kategorien trennen NUR am Semikolon: Kategorienamen auf Commons enthalten"
L[#L+1] = "   haeufig ein Komma (\"Films by X, Berlin\"), und die Lightroom-Seite trennt"
L[#L+1] = "   sie ebenfalls nur am Semikolon. Fuer Depicts und Nummern bleibt das Komma"
L[#L+1] = "   richtig - dort trennt Lua ebenso. */"
L[#L+1] = "function splitCats(s){"
L[#L+1] = "  return String(s || \"\").split(\";\").map(function(t){ return t.trim(); })"
L[#L+1] = "         .filter(function(t){ return t !== \"\"; });"
L[#L+1] = "}"
L[#L+1] = "function splitTokens(s){"
L[#L+1] = "  return String(s || \"\").split(/[;,]/).map(function(t){ return t.trim(); })"
L[#L+1] = "         .filter(function(t){ return t !== \"\"; });"
L[#L+1] = "}"
L[#L+1] = "function parseToken(tok){"
L[#L+1] = "  var hash = tok.indexOf(\"#\");"
L[#L+1] = "  var id = (hash < 0 ? tok : tok.slice(0, hash)).trim();"
L[#L+1] = "  var label = hash < 0 ? \"\" : tok.slice(hash + 1).trim();"
L[#L+1] = "  var m = id.match(/^[Qq](\\d+)$/);"
L[#L+1] = "  return m ? { id: \"Q\" + m[1], label: label } : null;"
L[#L+1] = "}"
L[#L+1] = "function tokenText(e){ return e.label ? e.id + \" # \" + e.label : e.id; }"
L[#L+1] = ""
L[#L+1] = "var SETS = null;"
L[#L+1] = "/* In diesem Tab an den Sets etwas geaendert? Dann ist DIESER Tab massgeblich:"
L[#L+1] = "   keine Uebernahme aus Lightroom mehr, und die Sets reisen beim Speichern"
L[#L+1] = "   mit. Ein Tab ohne Aenderung schreibt die Sets nie zurueck. */"
L[#L+1] = "var setsChanged = false;"
L[#L+1] = "var setsTimer = null;"
L[#L+1] = "var lastResultPost = 0;"
L[#L+1] = "/* Die Bruecke haelt genau EIN wartendes Ergebnis; Lightroom holt es etwa"
L[#L+1] = "   jede Sekunde ab. Ein Sets-Ergebnis direkt nach einem Foto-Ergebnis wuerde"
L[#L+1] = "   dieses ueberschreiben - deshalb so lange warten. */"
L[#L+1] = "var RESULT_GAP_MS = 3000;"
L[#L+1] = ""
L[#L+1] = "/* Sets SOFORT an Lightroom geben (nur im Brueckenbetrieb), ohne ein Foto zu"
L[#L+1] = "   schreiben. */"
L[#L+1] = "function persistSets(meldung){"
L[#L+1] = "  setsChanged = true;"
L[#L+1] = "  if (!BRIDGE) { setStatus(t(\"setsNeedSave\"), \"dirty\"); return; }"
L[#L+1] = "  if (setsTimer) clearTimeout(setsTimer);"
L[#L+1] = "  var warten = Math.max(0, lastResultPost + RESULT_GAP_MS - Date.now());"
L[#L+1] = "  setsTimer = setTimeout(function(){"
L[#L+1] = "    setsTimer = null;"
