L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Sprachen, in denen gesucht wird. Für Personen ist das meist gleichgültig –"
L[#L+1] = "   ein Name lautet überall gleich. Für Sachen nicht: „Kamera“, „camera“ und"
L[#L+1] = "   „appareil photo“ sind drei verschiedene Zeichenketten, und die Präfixsuche"
L[#L+1] = "   von Wikidata findet nur, was in der abgefragten Sprache steht. Deshalb wird"
L[#L+1] = "   in mehreren Sprachen zugleich gesucht: in der Oberflächensprache, auf"
L[#L+1] = "   Englisch als der am besten gepflegten Sprache, und in allen Sprachen, für"
L[#L+1] = "   die dieses Foto bereits eine Bildunterschrift hat – wer italienische"
L[#L+1] = "   Captions schreibt, sucht vermutlich auch mit italienischen Begriffen. */"
L[#L+1] = "function searchLanguages() {"
