L[#L+1] = "    }"
L[#L+1] = "  }"
L[#L+1] = "  add(UI);"
L[#L+1] = "  add(\"en\");"
L[#L+1] = "  state.captions.forEach(function(c){ add(c.lang); });"
L[#L+1] = "  return out;"
L[#L+1] = "}"
