L[#L+1] = "      return (d.search || []).map(function(e){"
L[#L+1] = "        return { id:e.id, label:e.label || \"\", description:e.description || \"\" };"
L[#L+1] = "      });"
L[#L+1] = "    })"
L[#L+1] = "    .catch(function(){ return []; });"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Volltextsuche. Sie durchsucht Wikidata sprachübergreifend und ist damit die"
L[#L+1] = "   breiteste Stufe – auch für Sprachen, die oben nicht abgefragt werden. */"
L[#L+1] = "function searchFulltext(term){"
L[#L+1] = "  return api({ action:\"query\", list:\"search\", srsearch:term,"
L[#L+1] = "               srnamespace:0, srlimit:MAX_HITS })"
