L[#L+1] = "    })"
L[#L+1] = "    .catch(function(){ return []; });"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Bezeichnungen und Beschreibungen zu einer QID-Liste, in der Reihenfolge der"
L[#L+1] = "   Liste. Bevorzugt die Oberflächensprache, dann Englisch, dann irgendeine"
