L[#L+1] = "          return v ? v.value : \"\";"
L[#L+1] = "        }"
L[#L+1] = "        return { id:id, label:pick(e.labels), description:pick(e.descriptions) };"
L[#L+1] = "      }).filter(Boolean);"
