L[#L+1] = "    .catch(function(){ return []; });"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Alle Stufen PARALLEL: die Präfixsuchen je Sprache und die Volltextsuche"
L[#L+1] = "   laufen gleichzeitig, nicht nacheinander – dadurch kostet die breitere Suche"
L[#L+1] = "   kaum mehr Zeit als die alte einsprachige. Zusammengeführt wird in der"
L[#L+1] = "   Reihenfolge der Sprachen (Oberflächensprache zuerst), die Volltexttreffer"
L[#L+1] = "   hängen hinten an. */"
L[#L+1] = "function search(term){"
L[#L+1] = "  var langs = searchLanguages();"
L[#L+1] = "  var jobs = langs.map(function(l){ return searchPrefix(term, l); });"
L[#L+1] = "  jobs.push(searchFulltext(term));"
L[#L+1] = "  return Promise.all(jobs).then(function(lists){"
