L[#L+1] = "    lists.forEach(function(list){"
L[#L+1] = "      list.forEach(function(r){"
L[#L+1] = "        if (r.id && !seen[r.id] && out.length < MAX_HITS) {"
L[#L+1] = "          seen[r.id] = true; out.push(r);"
L[#L+1] = "        }"
L[#L+1] = "      });"
L[#L+1] = "    });"
L[#L+1] = "    return out;"
L[#L+1] = "  });"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* ---------------------------------------------------------------------------"
L[#L+1] = "   Suchfeld mit Trefferliste. Pfeiltasten wählen, Eingabetaste übernimmt,"
L[#L+1] = "   Escape schließt – das ist der Teil, den ein Lightroom-Dialog nicht kann."
L[#L+1] = "--------------------------------------------------------------------------- */"
L[#L+1] = "function wireSearch(inputId, listId, onPick, recentKey, neuAnbieten){"
L[#L+1] = "  var input = document.getElementById(inputId);"
L[#L+1] = "  var list = document.getElementById(listId);"
L[#L+1] = "  var timer = null, generation = 0, hits = [], sel = -1;"
L[#L+1] = "  /* Wahr, sobald wirklich gesucht wurde. Nur dann bekommt die Liste unten"
L[#L+1] = "     den Weg zu einem neuen Wikidata-Eintrag - beim blossen Verlauf hat der"
L[#L+1] = "     Nutzer noch nichts gesucht, da waere das Angebot verfrüht. */"
L[#L+1] = "  var suchmodus = false;"
L[#L+1] = ""
L[#L+1] = "  /* Zuletzt benutzte Einträge. Sie kommen aus Lightroom (überleben also"
L[#L+1] = "     Fotowechsel und Neustart) und erscheinen beim Klick ins LEERE Feld."
