L[#L+1] = "    var out = [];"
L[#L+1] = "    for (var i = 0; i < quelle.length && out.length < MAX_HITS; i++) {"
L[#L+1] = "      var tok = parseToken(String(quelle[i] || \"\"));"
L[#L+1] = "      if (tok) out.push({ id: tok.id, label: tok.label || \"\","
L[#L+1] = "                          description: t(\"recentHint\") });"
L[#L+1] = "    }"
L[#L+1] = "    return out;"
L[#L+1] = "  }"
L[#L+1] = "  function showRecent(){"
