L[#L+1] = "    hits = r; sel = -1; render();"
L[#L+1] = "  }"
L[#L+1] = ""
L[#L+1] = "  function close(){ list.classList.remove(\"open\"); list.innerHTML = \"\";"
L[#L+1] = "                    hits = []; sel = -1; suchmodus = false; }"
L[#L+1] = ""
L[#L+1] = "  /* Haengt unter die Liste den Hinweis auf das Anlegewerkzeug. Der Text"
L[#L+1] = "     kommt ueber textContent hinein, die Adresse aus neuItemUrl() - also"
L[#L+1] = "     ausschliesslich aus festen Bestandteilen. */"
L[#L+1] = "  function neuZeile(){"
