L[#L+1] = "    var a = document.createElement(\"a\");"
L[#L+1] = "    a.href = neuItemUrl();"
L[#L+1] = "    a.target = \"_blank\";"
L[#L+1] = "    a.rel = \"noopener noreferrer\";"
L[#L+1] = "    a.textContent = t(\"newItem\") + \" \\u2197\";"
L[#L+1] = "    a.title = t(\"newItemTitle\");"
L[#L+1] = "    // Wie bei den Treffern: der Zeiger darf dem Eingabefeld den Fokus nicht"
L[#L+1] = "    // nehmen, sonst raeumt blur die Liste weg, bevor der Klick ankommt."
L[#L+1] = "    a.addEventListener(\"mousedown\", function(ev){ ev.preventDefault(); });"
