L[#L+1] = "      var b = document.createElement(\"button\");"
L[#L+1] = "      b.className = \"hit\" + (i === sel ? \" sel\" : \"\");"
L[#L+1] = "      b.type = \"button\";"
L[#L+1] = "      b.innerHTML = '<span class=\"qid\"></span><span class=\"lab\"></span>' +"
L[#L+1] = "                    '<span class=\"desc\"></span>';"
L[#L+1] = "      b.querySelector(\".qid\").textContent = h.id;"
L[#L+1] = "      b.querySelector(\".lab\").textContent = h.label || h.id;"
