L[#L+1] = "      var zeile = document.createElement(\"div\");"
L[#L+1] = "      zeile.className = \"hitrow\";"
L[#L+1] = "      zeile.appendChild(b);"
L[#L+1] = "      var wl = document.createElement(\"a\");"
L[#L+1] = "      wl.className = \"wdl\";"
L[#L+1] = "      if (wdLink(wl, h.id)) {"
L[#L+1] = "        wl.textContent = \"\\u2197\";"
L[#L+1] = "        // Wie beim Treffer: der Zeiger darf dem Eingabefeld den Fokus nicht"
L[#L+1] = "        // nehmen, sonst raeumt blur die Liste vor dem Klick weg."
L[#L+1] = "        wl.addEventListener(\"mousedown\", function(ev){ ev.preventDefault(); });"
L[#L+1] = "        zeile.appendChild(wl);"
L[#L+1] = "      }"
L[#L+1] = "      list.appendChild(zeile);"
L[#L+1] = "    });"
L[#L+1] = "    neuZeile();"
L[#L+1] = "    list.classList.add(\"open\");"
L[#L+1] = "  }"
L[#L+1] = "  function state_(text){"
L[#L+1] = "    list.innerHTML = '<div class=\"state\"></div>';"
L[#L+1] = "    list.firstChild.textContent = text;"
L[#L+1] = "    neuZeile();"
L[#L+1] = "    list.classList.add(\"open\");"
L[#L+1] = "  }"
L[#L+1] = "  function take(hit){"
L[#L+1] = "    onPick({ id: hit.id, label: hit.label || \"\" });"
