L[#L+1] = "  }"
L[#L+1] = ""
L[#L+1] = "  input.addEventListener(\"input\", function(){"
L[#L+1] = "    var term = input.value.trim();"
L[#L+1] = "    generation++;"
L[#L+1] = "    var mine = generation;"
