L[#L+1] = "    state_(t(\"searching\"));"
L[#L+1] = "    timer = setTimeout(function(){"
L[#L+1] = "      search(term).then(function(res){"
L[#L+1] = "        if (mine !== generation) return;"
L[#L+1] = "        hits = res; sel = res.length ? 0 : -1;"
L[#L+1] = "        if (!res.length) { state_(t(\"noHits\")); return; }"
L[#L+1] = "        render();"
L[#L+1] = "      }).catch(function(){"
L[#L+1] = "        if (mine !== generation) return;"
L[#L+1] = "        state_(t(\"offline\"));"
L[#L+1] = "      });"
L[#L+1] = "    }, DEBOUNCE);"
L[#L+1] = "  });"
L[#L+1] = ""
L[#L+1] = "  input.addEventListener(\"focus\", function(){"
L[#L+1] = "    if (input.value.trim() === \"\") showRecent();"
L[#L+1] = "  });"
L[#L+1] = ""
L[#L+1] = "  input.addEventListener(\"keydown\", function(ev){"
L[#L+1] = "    if (ev.key === \"ArrowDown\" || ev.key === \"ArrowUp\") {"
