L[#L+1] = "  });"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Kategorien sind freier Text ohne Q-Nummer, deshalb keine Wikidata-Suche,"
L[#L+1] = "   sondern nur der Verlauf: Klick ins leere Feld zeigt die letzten Einträge,"
L[#L+1] = "   Tippen engt sie ein (Teiltreffer, Groß- und Kleinschreibung egal). Enter"
L[#L+1] = "   übernimmt die Auswahl aus der Liste, sonst den getippten Text - so bleibt"
L[#L+1] = "   eine ganz neue Kategorie genauso schnell eingetragen wie vorher. */"
L[#L+1] = "function wireCategoryInput(){"
L[#L+1] = "  var input = document.getElementById(\"catInput\");"
L[#L+1] = "  var list = document.getElementById(\"catResults\");"
