L[#L+1] = ""
L[#L+1] = "  function saeubern(text){"
L[#L+1] = "    return String(text || \"\").trim().replace(/^Category:\\s*/i, \"\");"
L[#L+1] = "  }"
L[#L+1] = "  function schliessen(){"
L[#L+1] = "    list.classList.remove(\"open\"); list.innerHTML = \"\"; treffer = []; sel = -1;"
L[#L+1] = "  }"
L[#L+1] = "  function passende(){"
L[#L+1] = "    var quelle = (PAYLOAD.recent && PAYLOAD.recent.categories) || [];"
