L[#L+1] = "      var b = document.createElement(\"button\");"
L[#L+1] = "      b.className = \"hit\" + (i === sel ? \" sel\" : \"\");"
L[#L+1] = "      b.type = \"button\";"
L[#L+1] = "      var l = document.createElement(\"span\"); l.className = \"lab\";"
L[#L+1] = "      l.textContent = name;"
L[#L+1] = "      var d = document.createElement(\"span\"); d.className = \"desc\";"
L[#L+1] = "      d.textContent = t(\"recentHint\");"
L[#L+1] = "      b.appendChild(l); b.appendChild(d);"
L[#L+1] = "      // Wie bei der Wikidata-Suche: der Zeiger darf dem Feld nicht den"
