L[#L+1] = "      b.addEventListener(\"mousedown\", function(ev){ ev.preventDefault(); });"
L[#L+1] = "      b.addEventListener(\"click\", function(){ uebernehmen(name); });"
L[#L+1] = "      list.appendChild(b);"
L[#L+1] = "    });"
L[#L+1] = "    list.classList.add(\"open\");"
L[#L+1] = "  }"
L[#L+1] = "  function anzeigen(){"
