L[#L+1] = ""
L[#L+1] = "/* ---------------------------------------------------------------------------"
L[#L+1] = "   Veranstaltungs-Sets: Q-Nummer, Vorlage, Galerie und Kategorien als Einheit."
L[#L+1] = "   Liegen in den Voreinstellungen von Lightroom (nicht im Browserspeicher,"
L[#L+1] = "   dessen Herkunft bei jedem Start einen neuen Port hat) und reisen mit dem"
L[#L+1] = "   Ergebnis zurueck. Beim Uebernehmen werden die Kategorien ALLER Sets entfernt (Liste und"
L[#L+1] = "   Weiterer Text) und die des gewaehlten Sets eingesetzt; andere bleiben."
L[#L+1] = "--------------------------------------------------------------------------- */"
L[#L+1] = "function renderSets(){"
L[#L+1] = "  var sel = document.getElementById(\"setSel\");"
L[#L+1] = "  sel.innerHTML = \"\";"
L[#L+1] = "  var o = document.createElement(\"option\");"
L[#L+1] = "  o.value = \"\"; o.textContent = t(\"setNone\");"
L[#L+1] = "  sel.appendChild(o);"
L[#L+1] = "  SETS.forEach(function(s, i){"
L[#L+1] = "    var op = document.createElement(\"option\");"
L[#L+1] = "    op.value = String(i); op.textContent = s.name;"
L[#L+1] = "    sel.appendChild(op);"
L[#L+1] = "  });"
L[#L+1] = "  document.getElementById(\"setDel\").disabled = SETS.length === 0;"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Kategorien beim Set-Wechsel (rein, ohne DOM): ALLE Kategorien, die zu"
L[#L+1] = "   irgendeinem gespeicherten Set gehoeren, verschwinden aus der Liste und als"
L[#L+1] = "   [[Category:…]] aus dem Weiteren Text; danach kommen die des neuen Sets in"
L[#L+1] = "   die Liste. Fremde Kategorien (Person, Handeintraege) bleiben stehen."
L[#L+1] = "   Verglichen wird wie auf Commons: _ = Leerzeichen, erster Buchstabe egal. */"
L[#L+1] = "var SETCATS = (function(){"
L[#L+1] = "  function norm(n){"
L[#L+1] = "    var v = String(n || \"\").replace(/_/g, \" \").replace(/\\s+/g, \" \").trim();"
L[#L+1] = "    return v.charAt(0).toUpperCase() + v.slice(1);"
L[#L+1] = "  }"
L[#L+1] = "  var LINK = /\\[\\[\\s*[Cc]ategory\\s*:\\s*([^\\]|]+?)\\s*(?:\\|[^\\]]*)?\\]\\]/g;"
L[#L+1] = "  function ausText(text){"
L[#L+1] = "    var out = [], m;"
L[#L+1] = "    LINK.lastIndex = 0;"
L[#L+1] = "    while ((m = LINK.exec(String(text || \"\")))) out.push(m[1]);"
L[#L+1] = "    return out;"
L[#L+1] = "  }"
L[#L+1] = "  /* schutz: Namen, die NIE entfernt werden (Kategorien der Zeigt-Eintraege -"
L[#L+1] = "     falls ein aelteres Set eine Personenkategorie enthaelt, bleibt sie). */"
L[#L+1] = "  function tausche(cats, freetext, sets, neu, schutz){"
L[#L+1] = "    var weg = {};"
L[#L+1] = "    (sets || []).forEach(function(st){"
L[#L+1] = "      (st.categories || []).forEach(function(c){ weg[norm(c)] = true; });"
L[#L+1] = "    });"
L[#L+1] = "    (schutz || []).forEach(function(c){ delete weg[norm(c)]; });"
L[#L+1] = "    var removed = 0;"
L[#L+1] = "    var bleibt = (cats || []).filter(function(c){"
L[#L+1] = "      if (weg[norm(c)]) { removed++; return false; }"
L[#L+1] = "      return true;"
L[#L+1] = "    });"
L[#L+1] = "    var zeilen = String(freetext || \"\").split(\"\\n\").map(function(z){"
L[#L+1] = "      var vorher = z;"
L[#L+1] = "      var nachher = z.replace(LINK, function(all, name){"
L[#L+1] = "        if (weg[norm(name)]) { removed++; return \"\"; }"
L[#L+1] = "        return all;"
L[#L+1] = "      });"
L[#L+1] = "      /* Zeile, die NUR aus entfernten Links bestand, ganz streichen */"
L[#L+1] = "      if (nachher !== vorher && nachher.trim() === \"\") return null;"
L[#L+1] = "      return nachher;"
L[#L+1] = "    }).filter(function(z){ return z !== null; });"
L[#L+1] = "    var gesehen = {};"
L[#L+1] = "    var neuCats = [];"
L[#L+1] = "    bleibt.concat(neu.categories || []).forEach(function(c){"
L[#L+1] = "      var k = norm(c);"
L[#L+1] = "      if (k && !gesehen[k]) { gesehen[k] = true; neuCats.push(c); }"
L[#L+1] = "    });"
L[#L+1] = "    return { categories: neuCats, freetext: zeilen.join(\"\\n\"), removed: removed };"
L[#L+1] = "  }"
L[#L+1] = "  return { norm: norm, ausText: ausText, tausche: tausche };"
L[#L+1] = "})();"
L[#L+1] = ""
L[#L+1] = "function applySet(s){"
