L[#L+1] = "  state.freetext = r.freetext;"
L[#L+1] = "  document.getElementById(\"freetext\").value = state.freetext;"
L[#L+1] = "  touch(); renderCreatedDuring(); renderCategories(); renderTemplate(); renderPreview();"
