L[#L+1] = "  });"
L[#L+1] = ""
L[#L+1] = "  /* Kategorien der Zeigt-Eintraege (Personen, Filme …) gehoeren zum FOTO,"
L[#L+1] = "     nicht zur Veranstaltung - sie kommen nicht ins Set. Erkannt an der"
L[#L+1] = "     Beschriftung des Chips, an P373 und am Commons-Link auf eine Kategorie."
L[#L+1] = "     Ohne Netz bleibt es bei den Beschriftungen. */"
L[#L+1] = "  function zeigtKategorien(fertig){"
L[#L+1] = "    var namen = state.depicts.map(function(e){ return e.label; })"
L[#L+1] = "                  .filter(function(x){ return x; });"
L[#L+1] = "    var ids = state.depicts.map(function(e){ return e.id; });"
L[#L+1] = "    if (!ids.length) { fertig(namen); return; }"
L[#L+1] = "    /* Antwortet Wikidata nicht, wird nach 4 s mit den Beschriftungen"
L[#L+1] = "       gespeichert - der Knopf darf nicht haengen bleiben. */"
L[#L+1] = "    var erledigt = false;"
L[#L+1] = "    function einmal(){ if (!erledigt) { erledigt = true; fertig(namen); } }"
L[#L+1] = "    setTimeout(einmal, 4000);"
L[#L+1] = "    api({ action: \"wbgetentities\", ids: ids.slice(0, 50).join(\"|\"),"
L[#L+1] = "          props: \"claims|sitelinks|labels\", sitefilter: \"commonswiki\","
L[#L+1] = "          languages: \"en|de|\" + UI })"
L[#L+1] = "    .then(function(d){"
L[#L+1] = "      var ents = (d && d.entities) || {};"
L[#L+1] = "      ids.forEach(function(id){"
L[#L+1] = "        var e = ents[id];"
L[#L+1] = "        if (!e) return;"
L[#L+1] = "        var k = p373Oder(e);"
L[#L+1] = "        if (k) namen.push(k);"
L[#L+1] = "        var sl = e.sitelinks && e.sitelinks.commonswiki;"
L[#L+1] = "        var tt = (sl && sl.title) || \"\";"
L[#L+1] = "        if (/^Category:/i.test(tt)) namen.push(tt.replace(/^Category:/i, \"\").trim());"
L[#L+1] = "        [\"en\", \"de\", UI].forEach(function(l){"
L[#L+1] = "          if (e.labels && e.labels[l]) namen.push(e.labels[l].value);"
L[#L+1] = "        });"
L[#L+1] = "      });"
L[#L+1] = "    })"
L[#L+1] = "    .catch(function(){})"
L[#L+1] = "    .then(einmal);"
L[#L+1] = "  }"
L[#L+1] = ""
L[#L+1] = "  function speichereSet(name, ausser){"
L[#L+1] = "    var nicht = {};"
L[#L+1] = "    (ausser || []).forEach(function(c){ nicht[SETCATS.norm(c)] = true; });"
L[#L+1] = "    var ausgelassen = 0;"
L[#L+1] = "    var neu = { name: name.slice(0, 60),"
L[#L+1] = "                createdDuring: state.createdDuring ? tokenText(state.createdDuring) : \"\","
L[#L+1] = "                eventTemplate: state.eventTemplate || \"\","
L[#L+1] = "                gallery: state.gallery || \"\","
L[#L+1] = "                /* Liste UND [[Category:…]] aus dem Weiteren Text: dort steht"
