L[#L+1] = "                categories: (function(){"
L[#L+1] = "                  var seen = {}, out = [];"
L[#L+1] = "                  state.categories.concat(SETCATS.ausText(state.freetext)).forEach(function(c){"
L[#L+1] = "                    var k = SETCATS.norm(c);"
L[#L+1] = "                    if (!k || seen[k]) return;"
L[#L+1] = "                    seen[k] = true;"
L[#L+1] = "                    if (nicht[k]) { ausgelassen++; return; }"
L[#L+1] = "                    out.push(c.trim());"
L[#L+1] = "                  });"
L[#L+1] = "                  return out;"
L[#L+1] = "                })() };"
L[#L+1] = "    var idx = -1;"
L[#L+1] = "    SETS.forEach(function(s, i){ if (s.name.toLowerCase() === neu.name.toLowerCase()) idx = i; });"
L[#L+1] = "    if (idx >= 0) SETS[idx] = neu; else if (SETS.length < 30) { SETS.push(neu); idx = SETS.length - 1; }"
L[#L+1] = "    else { setStatus(t(\"setFull\")); return; }"
L[#L+1] = "    document.getElementById(\"setName\").value = \"\";"
L[#L+1] = "    renderSets();"
L[#L+1] = "    if (idx >= 0) sel.value = String(idx);"
L[#L+1] = "    var meldung = t(\"setSaved\", neu.name, neu.categories.length) +"
L[#L+1] = "                  (ausgelassen ? \" \" + t(\"setSkippedPerson\", ausgelassen) : \"\");"
L[#L+1] = "    setStatus(meldung);"
L[#L+1] = "    persistSets(meldung);"
L[#L+1] = "  }"
L[#L+1] = "  document.getElementById(\"setDel\").addEventListener(\"click\", function(){"
