L[#L+1] = ""
L[#L+1] = "/* ---------------------------------------------------------------------------"
L[#L+1] = "   Darstellung"
L[#L+1] = "--------------------------------------------------------------------------- */"
L[#L+1] = "/* Adresse des Wikidata-Eintrags, nur fuer eine wohlgeformte Q-Nummer; sonst"
L[#L+1] = "   leer. Die Adresse besteht ausschliesslich aus festem Anfang und der"
L[#L+1] = "   geprueften Nummer. */"
L[#L+1] = "function wdUrl(id){"
L[#L+1] = "  return /^Q[1-9][0-9]*$/.test(String(id)) ? \"https://www.wikidata.org/wiki/\" + id : \"\";"
L[#L+1] = "}"
L[#L+1] = "function wdLink(a, id){"
