L[#L+1] = "  i.textContent = id + (u ? \" \\u2197\" : \"\");"
L[#L+1] = "  if (u) wdLink(i, id);"
L[#L+1] = "  var l = document.createElement(\"span\");"
L[#L+1] = "  l.className = \"lab\" + (label ? \"\" : \" empty\");"
L[#L+1] = "  l.textContent = label || t(\"noLabel\");"
L[#L+1] = "  var x = document.createElement(\"button\");"
L[#L+1] = "  x.className = \"x\"; x.type = \"button\"; x.title = t(\"remove\");"
L[#L+1] = "  x.textContent = \"✕\";"
L[#L+1] = "  x.addEventListener(\"click\", onRemove);"
L[#L+1] = "  el.appendChild(i); el.appendChild(l);"
L[#L+1] = "  if (onSwap) {"
