L[#L+1] = "    if (swapping) el.className += \" swap\";"
L[#L+1] = "  }"
L[#L+1] = "  el.appendChild(x);"
L[#L+1] = "  return el;"
L[#L+1] = "}"
L[#L+1] = "function plainChip(text, onRemove){"
L[#L+1] = "  var el = document.createElement(\"span\");"
L[#L+1] = "  el.className = \"chip\";"
L[#L+1] = "  var l = document.createElement(\"span\"); l.className = \"lab\"; l.textContent = text;"
L[#L+1] = "  var x = document.createElement(\"button\");"
