L[#L+1] = ""
L[#L+1] = "/* Index des Eintrags, der beim naechsten Treffer ersetzt wird; -1 = keiner. */"
L[#L+1] = "var swapIdx = -1;"
L[#L+1] = ""
L[#L+1] = "/* ---------------------------------------------------------------------------"
L[#L+1] = "   Person tauschen. Reine Logik ohne DOM und ohne Netz (wird ausserhalb des"
L[#L+1] = "   Browsers mit Zusicherungen geprueft). st = { depicts, categories,"
L[#L+1] = "   captions }; neu = { id, label }; info (alles optional):"
L[#L+1] = "     labels: { sprache: { alt, neu } }  Bezeichnungen je Unterschriftsprache"
L[#L+1] = "     catAlt: [Namen]  Kategorienamen, die zur alten Person gehoeren"
L[#L+1] = "     catNeu: Name     Kategoriename der neuen Person"
L[#L+1] = "     sitelinks: { sprache: { alt, neu } }  Artikeltitel in der Wikipedia"
L[#L+1] = "   Ersetzt auch im Wikitext (st.freetext): Interwiki-Links der Form"
L[#L+1] = "   [[:de:Titel|Text]] samt Ziel, Klartext und [[Category:...]]-Zeilen."
L[#L+1] = "   Gibt { captions, categories, wikitext } zurueck: wie viele Stellen"
L[#L+1] = "   geaendert wurden."
L[#L+1] = "--------------------------------------------------------------------------- */"
L[#L+1] = "var SWAP = (function(){"
L[#L+1] = "  function ersetze(text, alt, neu){"
L[#L+1] = "    var teile = String(text).split(alt);"
L[#L+1] = "    return { text: teile.join(neu), n: teile.length - 1 };"
L[#L+1] = "  }"
L[#L+1] = "  /* Ersetzt in EINER Zeile Klartext und Links getrennt. Links werden nur"
L[#L+1] = "     angefasst, wenn sie genau auf den alten Artikel oder die alte Kategorie"
L[#L+1] = "     zeigen; alle anderen Links bleiben unveraendert, ihr Text wird nicht"
L[#L+1] = "     durchsucht. Der neu eingesetzte Text wird nie ein zweites Mal geprueft. */"
L[#L+1] = "  function wikitext(text, alt, neu, info, istAlt, neuName, res){"
L[#L+1] = "    if (!text) return text;"
L[#L+1] = "    var labels = info.labels || {}, sl = info.sitelinks || {};"
L[#L+1] = "    return String(text).split(\"\\n\").map(function(zeile){"
L[#L+1] = "      var m = zeile.match(/^\\s*\\{\\{([a-z][a-z0-9-]*)\\|/i);"
L[#L+1] = "      var lang = m ? m[1].toLowerCase() : \"\";"
L[#L+1] = "      var p = labels[lang] || {};"
L[#L+1] = "      var ziel = p.neu || neu.label;"
L[#L+1] = "      var kand = [];"
L[#L+1] = "      [p.alt, alt.label].forEach(function(a){"
L[#L+1] = "        if (a && kand.indexOf(a) < 0) kand.push(a);"
L[#L+1] = "      });"
L[#L+1] = "      kand.sort(function(a, b){ return b.length - a.length; });"
L[#L+1] = ""
L[#L+1] = "      function klar(seg){"
L[#L+1] = "        if (!ziel || !seg) return seg;"
L[#L+1] = "        for (var i = 0; i < kand.length; i++) {"
L[#L+1] = "          if (kand[i] === ziel) return seg;"
L[#L+1] = "          var r = ersetze(seg, kand[i], ziel);"
L[#L+1] = "          if (r.n) { res.wikitext++; return r.text; }"
L[#L+1] = "        }"
L[#L+1] = "        return seg;"
L[#L+1] = "      }"
L[#L+1] = "      function verweis(inner){"
L[#L+1] = "        var w = inner.match(/^:([a-z][a-z0-9-]*):([^|]*)(?:\\|.*)?$/i);"
L[#L+1] = "        if (w) {"
L[#L+1] = "          var l2 = w[1].toLowerCase(), q = sl[l2] || {};"
