L[#L+1] = ""
L[#L+1] = "/* Bezeichnungen, Artikeltitel und P31 in EINEM Aufruf. Die Artikeltitel"
L[#L+1] = "   kommen aus den Sitelinks - existiert dort keiner, gibt es den Artikel"
L[#L+1] = "   nicht, und dann wird eben nicht verlinkt. */"
L[#L+1] = "function fetchDetails(qids, langs){"
L[#L+1] = "  if (!qids.length) return Promise.resolve();"
L[#L+1] = "  var askLangs = langs.slice();"
L[#L+1] = "  if (askLangs.indexOf(\"en\") < 0) askLangs.push(\"en\");"
L[#L+1] = "  var url = \"https://www.wikidata.org/w/api.php?action=wbgetentities\" +"
L[#L+1] = "    \"&format=json&origin=*&props=labels%7Csitelinks%7Cclaims\" +"
L[#L+1] = "    \"&ids=\" + encodeURIComponent(qids.join(\"|\")) +"
L[#L+1] = "    \"&languages=\" + encodeURIComponent(askLangs.join(\"|\")) +"
L[#L+1] = "    \"&sitefilter=\" + encodeURIComponent(askLangs.map(COMPOSE.langToWiki).join(\"|\"));"
L[#L+1] = "  return fetch(url).then(function(r){ return r.json(); }).then(function(j){"
L[#L+1] = "    var ents = (j && j.entities) || {};"
L[#L+1] = "    Object.keys(ents).forEach(function(qid){"
L[#L+1] = "      var e = ents[qid] || {};"
L[#L+1] = "      var L = {};"
L[#L+1] = "      Object.keys(e.labels || {}).forEach(function(l){ L[l] = e.labels[l].value; });"
L[#L+1] = "      DETAILS.labels[qid] = L;"
L[#L+1] = "      var S = {};"
L[#L+1] = "      Object.keys(e.sitelinks || {}).forEach(function(site){"
L[#L+1] = "        var m = site.match(/^(.+)wiki$/);"
L[#L+1] = "        if (m) S[m[1].replace(/_/g, \"-\")] = e.sitelinks[site].title;"
L[#L+1] = "      });"
L[#L+1] = "      DETAILS.sitelinks[qid] = S;"
L[#L+1] = "      var p31 = (e.claims || {}).P31 || [];"
L[#L+1] = "      DETAILS.human[qid] = p31.some(function(c){"
L[#L+1] = "        var v = c.mainsnak && c.mainsnak.datavalue && c.mainsnak.datavalue.value;"
L[#L+1] = "        return !!v && v.id === \"Q5\";"
L[#L+1] = "      });"
L[#L+1] = "    });"
L[#L+1] = "  });"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Eine Zeile je Zielsprache mit dem Feld fuer die Fuegung. Nur sinnvoll,"
L[#L+1] = "   wenn eine Veranstaltung gesetzt ist - ohne sie gibt es nichts zu fuegen. */"
L[#L+1] = "function renderConnectors(){"
L[#L+1] = "  var box = document.getElementById(\"connRows\");"
L[#L+1] = "  box.innerHTML = \"\";"
L[#L+1] = "  var ev = state.createdDuring;"
L[#L+1] = "  if (!ev) return;"
L[#L+1] = "  targetLangs().forEach(function(lang){"
L[#L+1] = "    var key = ev.id + \"|\" + lang;"
L[#L+1] = "    var row = document.createElement(\"div\");"
L[#L+1] = "    row.className = \"rowline\";"
L[#L+1] = "    row.style.marginTop = \".35rem\";"
L[#L+1] = "    var tag = document.createElement(\"span\");"
L[#L+1] = "    tag.className = \"qid\";"
L[#L+1] = "    tag.style.minWidth = \"3.2rem\";"
L[#L+1] = "    tag.textContent = lang;"
L[#L+1] = "    var inp = document.createElement(\"input\");"
L[#L+1] = "    inp.type = \"text\";"
L[#L+1] = "    inp.value = state.connectors[key] || \"\";"
L[#L+1] = "    inp.placeholder = t(\"connPh\");"
L[#L+1] = "    inp.addEventListener(\"input\", function(){"
L[#L+1] = "      state.connectors[key] = inp.value;"
L[#L+1] = "      dirty = true;"
L[#L+1] = "    });"
L[#L+1] = "    /* Zweites Feld: die gebeugte Anzeigeform. Leer lassen heisst \"nimm die"
L[#L+1] = "       Wikidata-Bezeichnung\" - fuer Sprachen ohne Flexion bleibt hier nichts"
L[#L+1] = "       zu tun. */"
L[#L+1] = "    var frm = document.createElement(\"input\");"
L[#L+1] = "    frm.type = \"text\";"
L[#L+1] = "    frm.value = state.forms[key] || \"\";"
L[#L+1] = "    frm.placeholder = t(\"formPh\");"
L[#L+1] = "    frm.addEventListener(\"input\", function(){"
L[#L+1] = "      state.forms[key] = frm.value;"
L[#L+1] = "      dirty = true;"
L[#L+1] = "    });"
L[#L+1] = "    row.appendChild(tag);"
L[#L+1] = "    row.appendChild(inp);"
L[#L+1] = "    row.appendChild(frm);"
L[#L+1] = "    box.appendChild(row);"
L[#L+1] = "  });"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Erzeugt Unterschriften und den markierten Beschreibungsblock. */"
L[#L+1] = "function composeAll(){"
L[#L+1] = "  var langs = targetLangs();"
L[#L+1] = "  if (!state.depicts.length) { setStatus(t(\"composeNoDepicts\")); return; }"
L[#L+1] = "  if (!langs.length) { setStatus(t(\"composeNoLangs\")); return; }"
L[#L+1] = ""
L[#L+1] = "  var ids = state.depicts.map(function(e){ return e.id; });"
L[#L+1] = "  if (state.createdDuring) ids.push(state.createdDuring.id);"
L[#L+1] = ""
L[#L+1] = "  setStatus(t(\"composeBusy\"));"
L[#L+1] = "  fetchDetails(ids, langs).then(function(){"
L[#L+1] = "    DETAILS.conn = state.connectors;"
L[#L+1] = "    DETAILS.form = state.forms;"
L[#L+1] = "    state.captions.forEach(function(c){"
L[#L+1] = "      var lang = (c.lang || \"\").trim().toLowerCase();"
L[#L+1] = "      if (langs.indexOf(lang) < 0) return;"
L[#L+1] = "      var text = COMPOSE.caption(state.depicts, state.createdDuring, lang, DETAILS);"
L[#L+1] = "      if (text) c.text = text;"
L[#L+1] = "    });"
L[#L+1] = "    var inner = COMPOSE.block(state.depicts, state.createdDuring, langs, DETAILS);"
L[#L+1] = "    state.freetext = COMPOSE.merge(state.freetext, inner);"
L[#L+1] = "    dirty = true;"
L[#L+1] = "    renderAll();"
L[#L+1] = "    setStatus(t(\"composeDone\", langs.length), \"done\");"
L[#L+1] = "  }).catch(function(){"
L[#L+1] = "    setStatus(t(\"composeFailed\"));"
L[#L+1] = "  });"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Die beiden Ueberschriften trennen das Feld sichtbar in seine zwei Haelften."
L[#L+1] = "   Sie stehen WIRKLICH im gespeicherten Text, sonst waeren sie im"
L[#L+1] = "   Metadaten-Bedienfeld von Lightroom nicht zu sehen - das zeigt den Wert"
L[#L+1] = "   unveraendert an. Beim Einlesen und beim Hochladen werden sie wieder"
L[#L+1] = "   entfernt; auf Commons haetten sie als Aufzaehlungszeichen nichts zu"
L[#L+1] = "   suchen. Wer eine dieser Zeilen selbst schreibt, verliert sie deshalb. */"
L[#L+1] = "var HEAD_SDC = \"# Structured Data\";"
L[#L+1] = "var HEAD_WIKI = \"# Wikitext\";"
L[#L+1] = ""
L[#L+1] = "function isHeading(line){"
L[#L+1] = "  var l = String(line || \"\").trim();"
L[#L+1] = "  return l === HEAD_SDC || l === HEAD_WIKI;"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "function buildWikitext(){"
L[#L+1] = "  var daten = [], seen = {};"
L[#L+1] = "  state.captions.forEach(function(c){"
L[#L+1] = "    var l = (c.lang || \"\").trim().toLowerCase();"
L[#L+1] = "    var t = (c.text || \"\").trim();"
L[#L+1] = "    if (/^[a-z]{2}[a-z0-9-]*$/.test(l) && t && !seen[l]) {"
L[#L+1] = "      seen[l] = true;"
L[#L+1] = "      daten.push(\"caption_\" + l + \"=\" + t);"
L[#L+1] = "    }"
L[#L+1] = "  });"
L[#L+1] = "  state.depicts.forEach(function(e){ daten.push(\"depicts=\" + tokenText(e)); });"
L[#L+1] = "  if (state.createdDuring) {"
L[#L+1] = "    daten.push(\"created_during=\" + tokenText(state.createdDuring));"
L[#L+1] = "  }"
L[#L+1] = "  /* Eigener Schluessel, kein Freitext: beim Hochladen wandert die Vorlage"
L[#L+1] = "     hinter die Infobox und nicht in die Beschreibung. */"
L[#L+1] = "  if (state.eventTemplate) {"
L[#L+1] = "    daten.push(\"event_template=\" + state.eventTemplate);"
L[#L+1] = "  }"
L[#L+1] = "  /* Galerie dieses Fotos (Veranstaltungs-Set): eigener Schluessel wie die"
L[#L+1] = "     Vorlage, beim Hochladen ersetzt er die Galerie des Export-Dialogs. */"
L[#L+1] = "  if (state.gallery) {"
L[#L+1] = "    daten.push(\"gallery=\" + state.gallery);"
L[#L+1] = "  }"
L[#L+1] = ""
L[#L+1] = "  /* Der Freitext kann Ueberschriften aus einem frueheren Durchlauf"
L[#L+1] = "     enthalten - sie duerfen sich nicht vermehren. */"
L[#L+1] = "  var ft = String(state.freetext || \"\").split(/\\r\\n|\\r|\\n/)"
L[#L+1] = "    .filter(function(z){ return !isHeading(z); }).join(\"\\n\").trim();"
L[#L+1] = ""
L[#L+1] = "  var out = [];"
L[#L+1] = "  if (daten.length) { out.push(HEAD_SDC); out = out.concat(daten); }"
L[#L+1] = "  if (ft) {"
L[#L+1] = "    if (out.length) out.push(\"\");"
L[#L+1] = "    out.push(HEAD_WIKI);"
L[#L+1] = "    out.push(ft);"
L[#L+1] = "  }"
L[#L+1] = "  return out.join(\"\\n\");"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Eine Stelle fuer alles Kopieren. navigator.clipboard gibt es nur im"
L[#L+1] = "   sicheren Kontext; http://127.0.0.1 gilt als sicher, eine als Datei"
L[#L+1] = "   geoeffnete Seite nicht zwingend - daher der Rueckfall auf execCommand. */"
L[#L+1] = "function copyText(text){"
L[#L+1] = "  if (!text) return Promise.reject(new Error(\"leer\"));"
L[#L+1] = "  if (navigator.clipboard && navigator.clipboard.writeText) {"
L[#L+1] = "    return navigator.clipboard.writeText(text);"
L[#L+1] = "  }"
L[#L+1] = "  return new Promise(function(resolve, reject){"
L[#L+1] = "    var ta = document.createElement(\"textarea\");"
L[#L+1] = "    ta.value = text;"
L[#L+1] = "    ta.setAttribute(\"readonly\", \"\");"
L[#L+1] = "    ta.style.position = \"fixed\";"
L[#L+1] = "    ta.style.top = \"-1000px\";"
L[#L+1] = "    document.body.appendChild(ta);"
L[#L+1] = "    ta.select();"
L[#L+1] = "    var ok = false;"
L[#L+1] = "    try { ok = document.execCommand(\"copy\"); } catch (e) { ok = false; }"
L[#L+1] = "    document.body.removeChild(ta);"
L[#L+1] = "    if (ok) { resolve(); } else { reject(new Error(\"execCommand\")); }"
L[#L+1] = "  });"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* Kategorien stehen NICHT im Wikitext - sie gehen in ihr eigenes Lightroom-"
L[#L+1] = "   Feld. Gespeichert werden sie trotzdem, deshalb gehoeren sie in die"
L[#L+1] = "   Vorschau, aber sichtbar abgesetzt. Sie duerfen NIE in buildWikitext"
L[#L+1] = "   geraten: dessen Ergebnis landet in description_all. */"
L[#L+1] = "function appendCatPreview(pre){"
L[#L+1] = "  if (!state.categories.length) return;"
L[#L+1] = "  if (pre.firstChild) pre.appendChild(document.createTextNode(\"\\n\"));"
L[#L+1] = "  var hh = document.createElement(\"span\");"
L[#L+1] = "  hh.className = \"h\";"
L[#L+1] = "  hh.textContent = t(\"previewCats\");"
L[#L+1] = "  pre.appendChild(hh);"
L[#L+1] = "  pre.appendChild(document.createTextNode(\"\\n\"));"
L[#L+1] = "  state.categories.forEach(function(c){"
L[#L+1] = "    var k = document.createElement(\"span\");"
L[#L+1] = "    k.className = \"k\"; k.textContent = \"categories=\";"
L[#L+1] = "    pre.appendChild(k);"
L[#L+1] = "    pre.appendChild(document.createTextNode(c + \"\\n\"));"
L[#L+1] = "  });"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* ---------------------------------------------------------------------------"
L[#L+1] = "   Dateiname-Vorschlag. Reine Logik ohne DOM (wird ausserhalb des Browsers"
L[#L+1] = "   geprueft). Nimmt die englische Unterschrift, sonst die erste vorhandene;"
L[#L+1] = "   entfernt, was Commons in Dateinamen nicht zulaesst (# < > [ ] | { } : / \\"
L[#L+1] = "   und Steuerzeichen), fasst Leerraum zusammen und kuerzt auf 200 Zeichen an"
L[#L+1] = "   einer Wortgrenze. Keine Dateiendung: das Ausgabeformat steht hier nicht fest."
L[#L+1] = "--------------------------------------------------------------------------- */"
L[#L+1] = "var FILENAME = (function(){"
L[#L+1] = "  function bereinige(text){"
L[#L+1] = "    var t = String(text || \"\")"
L[#L+1] = "      .replace(/\\[\\[:?[a-z][a-z0-9-]*:[^|\\]]*\\|([^\\]]*)\\]\\]/gi, \"$1\")"
L[#L+1] = "      .replace(/\\[\\[([^|\\]]*)\\|([^\\]]*)\\]\\]/g, \"$2\")"
L[#L+1] = "      .replace(/[\\u0000-\\u001f\\u007f#<>\\[\\]|{}:\\/\\\\_~]/g, \" \")"
L[#L+1] = "      .replace(/%[0-9a-f]{2}/gi, \" \")"
L[#L+1] = "      .replace(/\\s+/g, \" \").trim();"
L[#L+1] = "    if (t.length > 200) {"
L[#L+1] = "      t = t.slice(0, 200);"
L[#L+1] = "      var sp = t.lastIndexOf(\" \");"
L[#L+1] = "      if (sp > 120) t = t.slice(0, sp);"
L[#L+1] = "      t = t.trim();"
L[#L+1] = "    }"
L[#L+1] = "    return t.replace(/[.\\s]+$/, \"\");"
L[#L+1] = "  }"
L[#L+1] = "  function vorschlag(captions){"
L[#L+1] = "    var en = \"\", erste = \"\";"
L[#L+1] = "    (captions || []).forEach(function(c){"
L[#L+1] = "      var l = String(c.lang || \"\").trim().toLowerCase();"
L[#L+1] = "      var x = String(c.text || \"\").trim();"
L[#L+1] = "      if (!x) return;"
L[#L+1] = "      if (l === \"en\" && !en) en = x;"
L[#L+1] = "      if (!erste) erste = x;"
L[#L+1] = "    });"
L[#L+1] = "    return bereinige(en || erste);"
L[#L+1] = "  }"
L[#L+1] = "  /* Die bereinigte Unterschrift genau einer Sprache, \"\" wenn es keine gibt. */"
L[#L+1] = "  function ausSprache(captions, lang){"
L[#L+1] = "    var out = \"\";"
L[#L+1] = "    (captions || []).forEach(function(c){"
L[#L+1] = "      if (!out && String(c.lang || \"\").trim().toLowerCase() === lang) {"
L[#L+1] = "        out = bereinige(c.text);"
L[#L+1] = "      }"
L[#L+1] = "    });"
L[#L+1] = "    return out;"
L[#L+1] = "  }"
L[#L+1] = "  return { bereinige: bereinige, vorschlag: vorschlag, ausSprache: ausSprache };"
L[#L+1] = "})();"
L[#L+1] = ""
L[#L+1] = "function renderFilename(){"
L[#L+1] = "  var out = document.getElementById(\"fnOut\");"
L[#L+1] = "  if (!out) return;"
L[#L+1] = "  var v = FILENAME.vorschlag(state.captions);"
L[#L+1] = "  out.value = v;"
L[#L+1] = "  out.placeholder = t(\"fnNone\");"
L[#L+1] = "  document.getElementById(\"fnCopy\").disabled = !v;"
L[#L+1] = "  [\"De\", \"En\"].forEach(function(L){"
L[#L+1] = "    document.getElementById(\"fnCopy\" + L).disabled ="
L[#L+1] = "      !FILENAME.ausSprache(state.captions, L.toLowerCase());"
L[#L+1] = "  });"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "function renderPreview(){"
L[#L+1] = "  renderFilename();"
L[#L+1] = "  var pre = document.getElementById(\"preview\");"
L[#L+1] = "  var text = buildWikitext();"
L[#L+1] = "  pre.innerHTML = \"\";"
L[#L+1] = "  if (!text) {"
L[#L+1] = "    if (state.categories.length) { appendCatPreview(pre); return; }"
L[#L+1] = "    pre.textContent = t(\"previewEmpty\"); return;"
L[#L+1] = "  }"
L[#L+1] = "  text.split(\"\\n\").forEach(function(line){"
L[#L+1] = "    if (isHeading(line)) {"
L[#L+1] = "      var hh = document.createElement(\"span\");"
L[#L+1] = "      hh.className = \"h\";"
L[#L+1] = "      hh.textContent = line;"
L[#L+1] = "      pre.appendChild(hh);"
L[#L+1] = "      pre.appendChild(document.createTextNode(\"\\n\"));"
L[#L+1] = "      return;"
L[#L+1] = "    }"
L[#L+1] = "    var m = line.match(/^([a-z_0-9]+)=(.*)$/);"
L[#L+1] = "    if (m) {"
L[#L+1] = "      var k = document.createElement(\"span\");"
L[#L+1] = "      k.className = \"k\"; k.textContent = m[1] + \"=\";"
L[#L+1] = "      pre.appendChild(k);"
L[#L+1] = "      var rest = m[2], h = rest.indexOf(\"#\");"
L[#L+1] = "      if (h >= 0) {"
L[#L+1] = "        pre.appendChild(document.createTextNode(rest.slice(0, h)));"
L[#L+1] = "        var c = document.createElement(\"span\");"
L[#L+1] = "        c.className = \"c\"; c.textContent = rest.slice(h);"
L[#L+1] = "        pre.appendChild(c);"
L[#L+1] = "      } else {"
L[#L+1] = "        pre.appendChild(document.createTextNode(rest));"
L[#L+1] = "      }"
L[#L+1] = "    } else {"
L[#L+1] = "      pre.appendChild(document.createTextNode(line));"
L[#L+1] = "    }"
L[#L+1] = "    pre.appendChild(document.createTextNode(\"\\n\"));"
L[#L+1] = "  });"
L[#L+1] = "  appendCatPreview(pre);"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "function renderAll(){"
L[#L+1] = "  renderDepicts(); renderCreatedDuring(); renderCategories();"
L[#L+1] = "  renderCaptions(); renderConnectors(); renderTemplate(); renderSets(); renderPreview();"
L[#L+1] = "  document.getElementById(\"freetext\").value = state.freetext;"
L[#L+1] = "  applyWorkflowView();"
L[#L+1] = "  renderApplyAll();"
L[#L+1] = "  renderWorkflowNote();"
L[#L+1] = "}"
L[#L+1] = "function touch(){"
L[#L+1] = "  dirty = true;"
L[#L+1] = "  var s = document.getElementById(\"status\");"
L[#L+1] = "  s.className = \"status dirty\";"
L[#L+1] = "  s.textContent = t(\"unsaved\");"
L[#L+1] = "  renderPreview();"
L[#L+1] = "}"
L[#L+1] = ""
L[#L+1] = "/* ---------------------------------------------------------------------------"
L[#L+1] = "   Kategorievorschläge: zu jeder eingetragenen Nummer die Commons-Kategorie"
L[#L+1] = "   (P373) holen, ersatzweise den Commons-Link des Items, sofern er auf eine"
L[#L+1] = "   KATEGORIE zeigt. Nichts wird erfunden: gibt es beides nicht, wird keine"
L[#L+1] = "   Kategorie vorgeschlagen (kein Raten aus der Bezeichnung)."
L[#L+1] = "--------------------------------------------------------------------------- */"
L[#L+1] = "function suggestCategories(){"
L[#L+1] = "  var ids = state.depicts.map(function(e){ return e.id; });"
L[#L+1] = "  if (state.createdDuring) ids.push(state.createdDuring.id);"
L[#L+1] = "  var btn = document.getElementById(\"catSuggest\");"
L[#L+1] = "  if (!ids.length) { setStatus(t(\"noQids\")); return; }"
L[#L+1] = "  btn.disabled = true;"
L[#L+1] = "  var old = btn.textContent;"
L[#L+1] = "  btn.textContent = t(\"searching\");"
L[#L+1] = "  api({ action:\"wbgetentities\", ids:ids.slice(0,50).join(\"|\"),"
L[#L+1] = "        props:\"claims|sitelinks\", sitefilter:\"commonswiki\" })"
L[#L+1] = "  .then(function(d){"
L[#L+1] = "    var ents = d.entities || {}, added = 0, ohne = [];"
L[#L+1] = "    var have = {};"
L[#L+1] = "    state.categories.forEach(function(c){ have[c.toLowerCase()] = true; });"
L[#L+1] = "    ids.forEach(function(id){"
