L[#L+1] = ""
L[#L+1] = "/* ---------------------------------------------------------------------------"
L[#L+1] = "   Brueckenbetrieb."
L[#L+1] = ""
L[#L+1] = "   Wird diese Seite von der Hintergrund-App ausgeliefert (http://127.0.0.1:PORT"
