L[#L+1] = "  var neueAuswahl = env.state.photoKey !== PAYLOAD.photoKey ||"
L[#L+1] = "    Number(env.state.photoCount || 1) !== photoCount();"
L[#L+1] = "  if (keep && keep.checked && neueAuswahl) {"
L[#L+1] = "    var k = JSON.parse(JSON.stringify({"
L[#L+1] = "      depicts: state.depicts, createdDuring: state.createdDuring,"
L[#L+1] = "      categories: state.categories, captions: state.captions,"
L[#L+1] = "      freetext: state.freetext, eventTemplate: state.eventTemplate,"
