L[#L+1] = "      ? t(\"switchedKeptN\", photoCount(), PAYLOAD.fileName || \"?\")"
L[#L+1] = "      : t(\"switchedKept\", PAYLOAD.fileName || \"?\"), \"dirty\");"
L[#L+1] = "    return;"
L[#L+1] = "  }"
L[#L+1] = "  if (dirty) {"
L[#L+1] = "    pendingState = env.state;"
