L[#L+1] = "function connectBridge(){"
L[#L+1] = "  try {"
L[#L+1] = "    if (BRIDGE.es) BRIDGE.es.close();"
L[#L+1] = "    var es = new EventSource(bridgeUrl(\"/events\"));"
L[#L+1] = "    BRIDGE.es = es;"
L[#L+1] = "    es.addEventListener(\"state\", function(ev){"
L[#L+1] = "      var env = null;"
L[#L+1] = "      try { env = JSON.parse(ev.data); } catch (e) { return; }"
L[#L+1] = "      onBridgeState(env);"
L[#L+1] = "    });"
L[#L+1] = "    es.addEventListener(\"open\", function(){"
L[#L+1] = "      setStatus(t(\"liveOn\"), \"done\");"
L[#L+1] = "      HB.last = Date.now();"
L[#L+1] = "      HB.lrIdle = 0;"
L[#L+1] = "      setBridgeState(\"live\");"
L[#L+1] = "    });"
L[#L+1] = "    es.addEventListener(\"hb\", function(ev){"
L[#L+1] = "      HB.last = Date.now();"
L[#L+1] = "      var d = null;"
L[#L+1] = "      try { d = JSON.parse(ev.data); } catch (e) { d = null; }"
L[#L+1] = "      HB.lrIdle = (d && typeof d.lrIdle === \"number\") ? d.lrIdle : 0;"
L[#L+1] = "      watchdogTick();"
L[#L+1] = "    });"
L[#L+1] = "    es.addEventListener(\"error\", function(){"
L[#L+1] = "      /* EventSource verbindet sich selbst neu. Solange er das noch versucht"
L[#L+1] = "         (readyState CONNECTING), ist es eine Stoerung; ist er endgueltig zu"
L[#L+1] = "         (CLOSED), ist die Seite veraltet. Beides zeigen wir gleich an - der"
L[#L+1] = "         Unterschied hilft dem Nutzer nicht, das Handeln ist dasselbe. */"
L[#L+1] = "      setStatus(t(\"liveRetry\"), \"dirty\");"
L[#L+1] = "      setBridgeState(\"lost\");"
L[#L+1] = "    });"
L[#L+1] = "  } catch (e) {"
L[#L+1] = "    setStatus(t(\"liveOff\"), \"dirty\");"
L[#L+1] = "    setBridgeState(\"lost\");"
L[#L+1] = "  }"
L[#L+1] = "}"
