L[#L+1] = "    method: \"POST\","
L[#L+1] = "    headers: { \"Content-Type\": \"application/json\" },"
L[#L+1] = "    body: out"
L[#L+1] = "  }).then(function(r){"
L[#L+1] = "    if (!r.ok) throw new Error(\"HTTP \" + r.status);"
L[#L+1] = "    dirty = false;"
L[#L+1] = "    forcedFields = null;"
L[#L+1] = "    setStatus(t(\"savedLive\"), \"done\");"
